-- Rollback de 202611200006_catalog_text_fixes.sql

update public.runes set description = $rd$Al impactar a un campeón enemigo con un ataque o una habilidad, tú y el campeón aliado cercano con la menor cantidad de vida se curan. \n\n Aliado: Recupera un 1.5% de Vida Máxima + un 5% de Poder de Habilidad. \n\n Tú: Recuperas un 1% de tu Vida Máxima + un 5% de tu Poder de Habildiad. Enfriamiento: 20 seg. \n\n Si eres un campeón cuerpo a cuerpo, la curazion tiene un 130% de efectividad. (No se activa si tú o tus aliados cercanos tienen la vida al máximo; tampoco se activa si no hay aliados cerca).$rd$ where id::text = '6a04bc5f681bf773dac12a83';
update public.runes set description = $rd$Tras salir del sigilo o usar un efecto de desplazamiento, salto o teleportación, tu siguiente ataque o habilidad contra un campeón enemigo en un lapso de 4 seg inflige de 15 a 65 de daño verdadero adicional (10 seg de enfriamiento). Este efecto se potencia al subir de nivel:\n\n Nivel 5: Infliges 5 de daño verdadero adicional.\n\n Nivel 9: Infliges 5 de daño verdadero adicional y obtienes un 10% de Velocidad de Movimiento durante 1.5 seg después de infligir el daño.$rd$ where id::text = '6a04bc5f681bf773dac12a84';
update public.runes set description = $rd$Cada 8 seg, el siguiente ataque se potencia e inflige entre 20 y 60 de daño adaptable adicional a los campeones enemigos.\n\n 80% para campeones a distancia.$rd$ where id::text = '6a04bc5f681bf773dac12a89';
update public.runes set description = $rd$Cuando te queda menos de un 60% de Vida, tus ataque contra campeones enemigos inglingen de un 5% a un 11% de daño adaptable adicional. \n\n Inflinges la cantidad máxima de daño adicional cuanto tienes menos de un 30% de Vida.$rd$ where id::text = '6a04bc5f681bf773dac12a8c';
update public.runes set description = $rd$A los 6 min de la partida, obtienes 2 de Daño de Ataque o 4 de Poder de Habilidad (adaptable). \n\n Cada 3 min, la bonificación aumenta a 5 o 10, 9 o 18, 14 o 28, etc.$rd$ where id::text = '6a04bc5f681bf773dac12a8d';
update public.runes set description = $rd$Infligir daño a un campeón enemigo con una habilidad activa le aplica una marca. Esto causa que tus próximos 2 ataques o lanzamientos de habilidades activas contra el inflijan daño adapatable adicional igual a (12-38 + 3% de daño de ataque adicional + 1.5% de poder de habilidad). (15 seg de enfriamiento).$rd$ where id::text = '6a04bc5f681bf773dac12a95';
update public.runes set description = $rd$Al recibir daño de un campeón, la habilidad o ataque actual y las 3 habilidades o ataques siguientes de un campeón contra ti y dentro de 1.5 seg. inflingen de 30 a 60 de daño menos (40 seg de enfriamiento)$rd$ where id::text = '6a04bc5f681bf773dac12a98';
update public.runes set description = $rd$Al destruir una planta, obtienes 10 de oro y los efectos potenciados de la planta. Las flores Álmicas cerca de las torretas otorgan bonificaciones adicionales.\n\n Frutamiel: Al consumirla, la curación aumenta un 20%.\n\n Brote del Vidente: Al destruirla, la visión otorgada dura un 20% más.\n\n Cono Explosivo: Tras el lanzamiento hacia atrás, otorga un 40% de Velocidad de Movimiento durante 2.5 seg.$rd$ where id::text = '6a04bc5f681bf773dac12a9b';
update public.runes set description = $rd$Al destruir una planta, obtienes de inmediato una semilla que reemplaza tu baratija durante 60 seg. La semilla madura y se autodestruye poco después de plantarla en una ubicación objetivo. También podrás recoger las semillas que aparezcan cuando un aliado destruya una planta.\n\n Las semillas se pueden obtener 2 min después del inicio de la partida.\n\n Cada planta tiene un enfriamiento individual de 30 seg.$rd$ where id::text = '6a04bc5f681bf773dac12aa6';
update public.runes set description = $rd$Gana 5 de Vida cada 5 seg. \n\n
Después de recibir daño de un campeón enemigo, regenera 3 + (1.5% de tu Vida faltante) durante los próximos 5 seg. Este efecto se duplica para los campeones cuerpo a cuerpo.$rd$ where id::text = '6a04bc5f681bf773dac12aa8';
update public.runes set description = $rd$Al derrivar campeones, recuperas un 10% de la Vida faltante y un 10% del Maná Máximo o la Energía máxima. Además, obtienes 35 de Velocidad de Movimiento durante 2 seg.$rd$ where id::text = '6a04bc5f681bf773dac12aac';
update public.runes set description = $rd$Obtienes un 3% de Velocidad de Ataque. Derriva monstruos, campeones enemigos o súbditos para obtener hasta un 18% de Velocidad de Ataque adicional$rd$ where id::text = '6a04bc5f681bf773dac12aad';
update public.runes set description = $rd$Al atacar a campeones enemigos, obtienes velocidad de ataque acumulable. Se acumula hasta 6 veces. Al alcanzar el máximo de acumulaciones, obtienes alcance adicional y puedes superar tu limite de velocidad de ataque.\n Cada acumulacion aumenta la Velocidad de Ataque de un 6 a un 14% (cuerpo a cuerpo) o de un 3.5 a un 8% (a distancia) durante 6 seg.\n Al alcanzar el máximo de acumulaciones, obtienes 25 (cuerpo a cuerpo) o 50 (a distancia) de alcance.$rd$ where id::text = '6a04bc5f681bf773dac12aae';
update public.runes set description = $rd$Tus ataques y habilidades inflingen un 6.5% de daño adaptable adicional a los campeones enemigos que tienen más de un 60% de Vida$rd$ where id::text = '6a04bc5f681bf773dac12ab4';
update public.rune_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Cada 8 seg, el siguiente ataque se potencia e inflige entre 20 y 60 de daño adaptable adicional a los campeones enemigos.\n\n 80% para campeones a distancia.$rd$::text)) where patch_id = 11 and rune_id = '6a04bc5f681bf773dac12a89';
