update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Versátil: Obtienes 14 de Daño de Ataque o 28 de Poder de Habilidad (adaptable). \n Invocación Álmica: Cada 60 seg obtienes 60 de oro, 25 de Vida y 2 de Daño de Ataque o 4 de Poder de Habilidad (adaptable); hasta un máximo de 250 de Vida y 20 de Daño de Ataque o 40 de Poder de Habilidad (adaptable). Inflinges 2 de daño adicional a los centinelas de visión que hayan sido revelados con Lente Revelados, Centinela de Control y Brote del Vidente. \n Obtienes un 10% de VElocidad de Movimiento al desplazarte hacia tu compañero perfecto fuera del combate. Si están a mas de 2500 unidades de distancia, esta bonificación aumenta a un 30%.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e076';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Luna siempre creciente: impactar a un campeón enemigo con 2 ataques o habilidades diferentes en un periodo de 1.8 seg inflinge daño físico adicional igual al 7% de la Vida Máxima del objetivo (3.5 para campeones a distancia). Además te otorga un escudo que absorbe una cantidad de daño igual a 140 + 35% de Daño de Ataque adicional (70 + 18% de Daño de Ataque adicional para campeones a distancia) durante 2 seg. (6 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e03d';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asombro: Otorga Daño de Ataque igual al 2% de Maná Máximo y restaura el 15% de todo el maná gastado. \n Carga de Maná: Aumenta el Maná Máximo en 14 cada vez que gastas maná o en cada ataque. Tiene un límite de 700 de Maná adicional y transforma a Manamune en Muramaná. Se activa hasta 3 veces cada 10 seg. Solo puedes llevar un objeto de Lágrima de la Diosa a la vez.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e030';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Infinidad: Los golpes críticos inflingen un 230% de daño en vez de 200%.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e036';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Sobremarcha: Obtienes un 5% de Velocidad de Movimiento. \n Frenesí de Poder: Al desplazarte y atacar, generas ataques energizados. Los ataques energizados obtienen 100 de alcance (50 de alcance para los ataques cuerpo a cuerpo), inflingen de 40 a 100 de daño mágico adicional y otorgan 60 de Velocidad de Movimiento durante 0.75 seg. Este daño rebota a un máximo de 5 enemigos cercanos y puede asestar golpes críticos. (inflinge entre un 50% y un 80% de daño adicional contra súbditos).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e031';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Descarga: Los ataques energizados inflingen 40 de daño mágico adicional. Al desplazarte y atacar generas ataques energizados$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e032';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Reforzado: Los ataques inflingen 15 de daño físico adicional al impacto contra campeones$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e033';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Cortar: +15 de Penetración de Armadura. \n Impulso: 3 seg después de salir del combate con campeones enemigos, obtiene 30 de Velocidad de Movimiento adicional (20 para campeones a distancia).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e034';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asombro: Otorga Daño de Ataque igual al 2% de Maná Máximo y restaura el 15% de todo el maná gastado.\n Impacto: Cuando un ataque impacta contra un campeón enemigo, drena un 1.5% del maná actual y le inflinge daño físico adicional equivalente al 3.5% (cuerpo a cuerpo)/3% (a distancia) del Maná Máximo.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e037';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Espada Encantada: Tras usar una habilidad, tu próximo ataque en los 10 seg siguientes inflinge un 10% de la Vida Máxima del objetivo como daño físico adicional (7% si el ataque es a distancia). Si el objetivo es un campeón, cura un 6% de la Vida Máxima del objetivo (2.5% si el ataque es a distancia). (1.5 seg de enfriamiento). El daño se reduce contra estructuras.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e038';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Severo: +50% del daño de ataque básico como daño físico adicional.\n Salvavidas: Al recibir daño que te haga bajar del 35% de vida, recibes un escudo equivalente al 75% de la adicional que se desvanece a lo largo de 5 s. (75 s de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e03a';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Furia del Viento: Los ataques impactan a 2 enemigos cercanos adicionales, cada uno inflinge un 55% de daño físico. Esos ataques pueden inflingir golpes criticos y activar efectos al impacto.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e03f';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Puñalada: +15 de Penetración de Armadura. \n Saqueador de Escudos: Inflingir daño a un campeón enemigo reduce los escudos que obtengan durante 3 seg. Los campeones cuerpo a cuerpo aplican un (10% de Daño de Ataque adicional + 40% de reduccion de escudo, con límite del 60%) Los campeones a distancia aplican un (10% de Daño de Ataque adicional + 25% de reducción de escudoi, con limite de 45%). Cuando inflinfes daño a un enemigo que no esta afectado por Saqueador de Escudos, reduce todos sus escudos por el mismo valor.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e040';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Desafiar: Si a un campeón al que le infligiste daño en los últimos 3 seg muere, el daño restante de Ignorar el Dolor se purifica y te curas durante 2 seg por una cantidad igual al 90% de Daño de Ataque adicional. \n Cauterizar: Almacena un 30% del daño físico y mágico recibido (12% para campeones a distancia) y recibe la cantidad almacenada como daño verdadero durante 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e041';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Ataques Arruinados: Los ataques inflingen daño físico adicional al impacto igual al 7% de la Vida actual del enemigo. (Los ataques cuerpo a cuerpo inflingen 10%). Daño mínimo: 15. Max. daño contra monstruos: 60. \n Drenar: Impactar al mismo campeón enemigo 3 veces con ataques básicos o habilidades lo ralentiza un 30% durante 1.5 seg (30 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e043';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Último Suspiro: Obtienes un 30% de Penetracion de Armadura. Los ataques que asestan golpes críticos obtienen un 6% de Penetracion de Armadura adicional. \n Sepsis: inflingir daño físico aplica un 50% de Heridas Graves a los campeones enemigos por 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e044';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asombro: Regenera un 10% del Maná gastado. \n Carga de Maná: Aumenta el maná máximo en 6 cada vez que gastas maná. Tiene un límite de 700 de Maná adicional. Se activa hasta 3 veces cada 10 seg. Solo puedes llevar un objeto de Lágrima de la Diosa a la vez.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e045';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Espada Encantada: Tras lanzar una habilidad, tu siguiente ataque básico dentro de 10 seg posteriores inflige daño físico adicional equivalente a un 135% x Daño de Ataque básico + 0 - 80 (según la Tasa de Críticos) y restaura Maná equivalente al 50% del daño infligido (1.5 seg de enfriamiento). \n Sifón de Maná: Los ataque restauran un  3% de tu Maná faltante al impacto.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e047';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Paliza: Al inflingir daño físico a los campeones enemigos, aplica un 50% de Heridas Graves durante 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e048';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$A Toda Vela: Obtienes un 5% de Velocidad de Movimiento. \n Capitán: Cada 4º ataque contra campeones y monstruos épicos inflinge daño físico adicional equivalente a un 160% básico mas un 5% de la vida máxima (los campeones a distancia inflingen un 40% del daño), que aumenta a un 240% basico mas un 9% de la vida máxima contra estructuras (los campeones a distancia inflingen un 40% del daño). \n Tripulacion de Abordaje: Los súbditos de asedio y los supersúbditos aliados cercanos obtienen entre 20 y 130 de Armadura (25% adicional si es un campeon a distancia) y entre 10 y 120 de Resistencia Mágica (25% adicional si es un campeón a distancia).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e049';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Fuerza del Dragón: Obtienen 20 de Aceleracion de Habilidad para habilidades básicas. \n Voluntad Enfocada: Al inflingir daño a enemigos o monstruos con habilidades, el daño de las habilidades y de la pasiva de tu campeon aumenta un 3% durante 6 seg. (Se puede acumular 4 veces). La acumulacion de Voluntad Enfocada tiene un bloqueo de 1 seg por cada lanzamiento de habilidad.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e04a';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Sombra: Los ataques inflingen 30 de daño mágico adicional al impacto. \n Yuxtaposición: Alterna entre los efectos al impacto de Luz y Oscuridad al atacar. Los ataques de Luz otorgan de 5 a 8 de Armadura y de Resistencia Mágica durante 5 seg. al impacto. Los ataques de Oscuridad otorgan un 10% de Penetración de Armadura y un 10% de Penetración de Magia durante 5 seg. al impacto. Cada efecto al impacto se acumula hasta 3 veces. Mientras tengas este objeto, la Penetración de Armadura y la Penetración de Magia adicionales que te otorga tendrán un máximo de 40%.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e04b';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Hender: Cada 1.75 seg, tu siguiente ataque inflinge una cantidad de daño físico adicional equivalente a 25 + 3% de tu vida máxima adicional (tambien aplica a las torretas) y genera una onda de choque que inflinge una cantidad de daño físico equivalente a 80 + 10% de tu vida máxima adicional a los enemigos que esten detrás del objetivo. Los campeones a distancia inflingen un 75% del daño.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e04c';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Fervor: +5% de velocidad de movimiento. \n Hoja encantada: Tras usar una habilidad, el siguiente ataque básico en los próximos 10 s inflinge daño físico adicional equivalente al 200% básico. (1,5 s de enfriamiento). El daño es menor contra estructuras. \n$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e04e';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Desgarrar: Inflingir daño físico a un campeón reduce su Armadura un 6% durante 6 seg y se acumula hasta 5 veces para llegar a una reduccion de 30%. \n Persecución: Obtienes 20 de Velocidad de Movimiento cuando inflinges daño físico. Obtienes 40 de Velocidad de Movimiento cuando te desplazas hacia campeones enemigos que tengan 5 acumulaciones de Desgarrar. Los campeones a distancia obtienen la mitad de las bonificaciones.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e050';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Navaja: +18 de Penetración de Armadura. \n Acechador Nocturno: El primer ataque contra un campeon inflingirá de 60 a 160 de daño físico adicional y lo ralentizará un 99% durante 0.35 seg (10 seg de enfriamiento). \n Los derribos de campeones restablecen el enfriamiento.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e052';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Golpes Certeros: Los ataques reducen el enfriamiento restante de tus habilidades básicas en un 15%. \n$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e053';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asesino: +10 de Penetración de Armadura. \n Muerte y Tributos: Al inflingir daño que dejaría a un campeón enemigo por debajo de (4% + 2% de Tasa de Criticos) de su Vida Máxima, lo ejecuta, aumenta de forma permanente el umbral de ejecución de Vida Máxima en un 0.1% y otorga 25 de oro adicional.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e054';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Enterrar: +8 de Penetración de Armadura. \n Anular: Otorga un escudo mágico que bloquea la siguiente habilidad enemiga. (35 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e055';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Pies Ligeros: +7% de velocidad de movimiento. \n Vals Espectral: Al impactar a un enemigo con un ataque, obtienes un 6% de Velocidad de Ataque y un 1% de Velocidad de Movimiento durante 6 segacumulable hasta 5 veces.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e057';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Golpe de Escudo de Luz: El primer ataque contra un campeón enemigo asesta un golpe crítico (6 seg de enfriamiento por cada objetivo), inflinge un 160% de daño y te restaura Vida igual a un 125% del Daño de Ataque básico + 6% de tu Vida faltante.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e058';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Salvaguarda: Otorga un escudo mágico que bloquea la siguiente habilidad enemiga. Cuando el escudo acaba, el daño recibido se reduce en un 40% durante 1 seg. (40 seg de enfriamiento).\n Elegancia: El poder de habilidad aumenta en 20 al estar bajo el efecto de Salvaguarda. Inflingir daño mágico a campeones enemigos con una habilidad activa reduce el enfriamiento de Salvaguarda en 4 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e05b';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Hiperdisparo: inflingir daño a un campeón enemigo con una habilidad a 600 unidades de distancia lo revela durante 8 seg. y aumenta el daño inflingido en un 10%. \n Concentración: Al activar Hiperdisparo, revelará a todos los campeones enemigos a 1200 unidades de distancia del objetivo durante 3 seg. (12 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e05c';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Flor de Fuego: Al inflingirle daño a un campeón enemigo con una habilidad activa, aparecerá una trampa a sus pies. Tras un brece retraso, la trampa inflinge daño mágico igual a 105 mas un 15% de poder de habilidad a los enemigos en su interior (8 seg de enfriamiento por objetivo). Si un objetivo es alcanzado por más de una trampa colocada por el mismo campeón dentro de un breve periodo, las trampas despues de la primera solo inflingirán un 20% de daño.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e064';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Sacrificio: Mientras tu aliado digno esté cerca, el 12% del daño que recibe se redirige a ti. Además, te curas un 10% del daño a campeones que inflinge tu aliado digno. \n Juramento: Cuando compras o vuelves a comprar este objeto designas un aliado que sea digno.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e065';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Paso de Nube: Obtienes un 5% de Velocidad de Movimiento. \n Derríbalo: Cada tercer ataque inflinge entre 150 y 210 de daño físico adicional (entre 120 y 168 para los campeones a distancia), que aumenta un 0.75% por cada 1% de Vida que le falte al objetivo. El daño físico adicional tiene un límite de un 75%.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e066';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Golpe Paralizante: Al inflingir daño físico a los campeones enemigos, aplica un 40% de Heridas Graves durante 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e068';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Corrupción del Vacío: Al combatir contra campeones enemigos, infliges un 2% de daño adicional por seg (hasta un máximo de 8%). Al nivel de fuerza máxima, obtienes un 10% (cuerpo a cuerpo) / 6% (a distancia) de Omnivampirismo. \n\n
Infusión del Vacío: Obtienes Poder de Habilidad equivalente a un 2% de tu Vida adicional$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e06c';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Acelerado: Las habilidades de daño y los ataques potenciados contra compeones inflingen 25-60 de daño mágico adicional (20 s de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e06d';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Espinas: Cuando recibes un ataque, inflinges (20 + 6% de armadura adicional + 1% de vida adicional) de daño mágico al atacante. \n Entrelazado: Cuando recibes el ataque de un campeón enemigo o le inflinges daño, le aplicas un 50% de Heridas Graves durante 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e06e';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Tiranía: Obtienes daño de ataque igual al 2.5% de tu Vida adicional. \n Reprensión: Obtienes hasta un 9% de Daño de Ataque aumentado según tu vida faltante. \n Obtienes la bonificación máxima de Reprensión al tener menos de un 30% de Vida.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e06f';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Tributo: Cada 30 seg, obtienes 1 orbe de energía que te orbita (máx 3 orbes). Al estar cerca de un aliado, las siguientes acciones activarán Tributo, lo que consumirá 1 orbe de energía para otorgarte 65 de oro y restaurarte entre 20 y 80 de Vida: \n 1. Inflingir daño a campeones o estructuras enemigas con habilidades o ataques. \n 2. Atacar a súbditos que tengan menos de un 65% de Vida. Esta acción tambien los ejecuta. Además, el oro que generen tus asesinatos de súbditos se entregará al aliado que esté más cerca de ti. \n 3. Tener 3 orbes y estar cerca de un súbdito cuando muere. \n Al activar Tributo, el aliado más cercano a ti obtiene acumulaciones de Tributo. \n Guardián: Inflinges 1 de daño adicional a los cCentinelas de Vision que hayan sido revelados con Lente Revelador, Centinela de Control y Brote Vidente. \n Restricción: No recibes oro al matar súbditos, pero obtienes una cantidad de oro que equivale a un 50% de la recompensa. El oro que generen tus asesinatos de súbditos se entregará al aliado que este más cerca de ti. Ademas el oro que obtienes al matar monstruos se reduce un 50%. \n Misión: Obten 750 de oro con este objeto para transformalo en Guadaña de Niebla Oscura. Esto te unirá al aliado con la mayor cantidad de acumulaciones de Tributo y los convertirá en los mejores compañeros.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e070';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Ruptura mágica: +8 de penetración mágica.\n Equilibrio: Los campeones sin maná obtienen un 75% de regeneración de vida adicional. \n Gran bravucón: Los ataques y habilidades activas inflingen 18 de daño físico adicional a los súbditos.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e071';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Gloria: Obtienes hasta 30 acumulaciones de gloria tras derribar a un campeón. Los campeones cuerpo a cuerpo obtienen 3 acumulaciones por cada asesinato y 2 acumulaciones por cada asistencia; los campeones a distancia obtienen 4 acumulaciones por cada asesinato y 2 acumulaciones por cada asistencia. Pierdes 10 acumulaciones al morir. \n Miedo: Obtienes 5 de Poder de Habilidad por cada acumulación de gloria que tengas. Al tener 10 acumulaciónes de gloria o mas, obtienes un 01% de Velocidad de Movimiento adicional.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e07b';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Angustia: Cada 4 seg que estés en combate contra un campeón, inflinges un 3% de tu Vida Máxima como daño mágico a los campeones enemigos cercanos y te curas un 250% del daño inflingido. La aceleracion de habilidad de los objetos no afecta a Angustia.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e07e';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Inmolar: Al estar en combate, inflinges una cantidad de daño mágico equivalente a entre 20 y 30 más un 1% de tu Vida adicional por segundo a los enemigos cercanos durante 5 seg. Inflinge un 125% de daño a monstruos y un 200% de daño a súbditos. \n Desolar: Al matar a un monstruo neutral o un enemigo inflinges una cantidad de daño mágico equivalente a 30 más un 2% de tu Vida adicional en el área circundante.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e07f';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Versátil: Obtienes 10 de Daño de Ataque o 20 de Poder de Habilidad (adaptable). \n Tributo: Cada 30 seg, obtienes 1 orbe de energía que te orbita (máx 3 orbes). Al estar cerca de un aliado, las siguientes acciones activarán Tributo, lo que consumirá 1 orbe de energía para otorgarte 65 de oro y restaurarte entre 20 y 80 de Vida: \n 1. Inflingir daño a campeones o estructuras enemigas con habilidades o ataques. \n 2. Atacar a súbditos que tengan menos de un 65% de Vida. Esta acción tambien los ejecuta. Además, el oro que generen tus asesinatos de súbditos se entregará al aliado que esté más cerca de ti. \n 3. Tener 3 orbes y estar cerca de un súbdito cuando muere. \n Al activar Tributo, el aliado más cercano a ti obtiene acumulaciones de Tributo. \n Guardián: Inflinges 1 de daño adicional a los cCentinelas de Vision que hayan sido revelados con Lente Revelador, Centinela de Control y Brote Vidente. \n Restricción: No recibes oro al matar súbditos, pero obtienes una cantidad de oro que equivale a un 50% de la recompensa. El oro que generen tus asesinatos de súbditos se entregará al aliado que este más cerca de ti. Ademas el oro que obtienes al matar monstruos se reduce un 50%. \n Misión: Obten 750 de oro con este objeto para transformalo en Guadaña de Niebla Oscura. Esto te unirá al aliado con la mayor cantidad de acumulaciones de Tributo y los convertirá en los mejores compañeros.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e082';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Intervención: Selecciona un área grande como objetivo. Despues de 2.5 seg, restauras entre 150 y 350 de Vida (según el nivel del aliado) a las unidades aliadas e inflinges un 10% de la Vida Máxima como daño verdadero a los campeones enemigos (Enfriamiento: 60 seg). Se puede lanzar aunque hayas muerto.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e087';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Carga Hex: Obtienes 20 de Aceleración de Habilidad para tu definitiva. \n\n Sobremarcha: Tras usar tu definitiva, obtienes un 40% de Velocidad de Ataque (20% para campeones a distancia) y un 20% de Velocidad de Movimiento (10% para campeones a distancia) durante 8 seg. (30 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e088';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Ira: los ataques inflingen 30 de Daño Mágico adicional. \n  Ataque Furioso: Los ataques básicos otorgan un 8% de Velocidad de Ataque y se puede acumular hasta cuatro veces. Al alcanzar el máximo de acumulaciones, cada tercer ataque básico activa un efecto al impacto adicional$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e08f';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asombro: Otorga una cantidad de poder de habilidad equivalente a un 1% del maná máximo y restaura un 25% o de todo el maná gastado. \n Carga de maná: Aumenta el maná máximo en 14 cada vez que se gaste maná. El límite de maná adicional es 700, lo que transforma Bastón del Arcángel en Abrazo de Serafín. Se activa hasta 3 veces cada 10 s. Solo se puede tener una lágrima de la diosa.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e094';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Heridas Graves: Al inflingir daño mágico a cmapeones enemigos, les aplicas un 40% de Heridas Graves durante 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e09a';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Equilibrio de poder: Obtienes 12 de Daño de Ataque o 20 de Poder de Habilidad \n\n
Conversión: Obtienes 5% de Omnivampirismo + 0.5% de Omnivampirismo por cada participación en derribos (hasta un 5% adicional y un máximo de 10% de Omnivampirismo)$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e09b';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Destino: +5% de Velocidad de Movimiento. \n Balance: +15 de Penetración de Magia. \n Muerte Inevitable: Las habilidades y los ataques potenciados asestan golpes críticos que inflingen un 20% de daño adicional contra enemigos que tengan menos de un 40% de Vida. \n\n$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e09d';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Danza de Hechizos: Inflingir daño mágico o daño verdadero a campeones otorga 30 de Velocidad de Movimiento durante 4 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e09e';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Contracorriente: Cuando recibes un golpe crítico de daño físico, obtienes 1 acumulaciones de Contracorriente. Cada acumulación otorga un 5% de Velocidad de Movimiento y un 5% de resistencia a ralentizaciones. Máximo de acumulaciones 4. \n Resiliencia: Los golpes críticos te inflingen un 30% menos de daño físico.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a3';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Arma Mortal: Inflingir daño con habilidades a un campeón enemigo reduce cualqueir escudi que obtenga durante 3 seg. Las habilidades de área de efecto aplican un (5% de Poder de Habilidad + 25)% de reducción de escudo, con límite de un 45%; las habilidades contra un solo objetivo aplican un (5% de Pder de Habilidad + 40)% de reducción de escudo, con límite de un 60%. Cuando inflinges daño a un enemigo que no está afectado por Arma Mortal, reduce todos sus escudos por el mismo valor.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e09f';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Conversión: Obtienes Poder de Habilidad igual a un 3.5% de la Vida adicional. \n Proyección: Cuando tengas al menos 950 de Vida adicional, obtiene un 20% de poder de habilidad como Armadura y un 10% de poder de habilidad como Resistencia Mágica (la cantidad máxima de bonificaciones se alcanza con 400 de Poder de Habilidad).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a0';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Caceria de almas: +15 de Penetración de Magia. \n Alma Errante: Cada vez que derribes a un campeon enemigo a los 3 seg despues de haberle inflingido daño, los enfriamientos de tus habilidad se reducen en un 25%. Robas un 10% de su Velocidad de Movimiento básica durante 10 seg y un 50% de su Aceleración de Habilidad hasta que reaparezcan. La aceleración de habilidad robada de esta forma se acumula.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a1';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Inmolar: Inflinge de 5 a 10 de daño mágico por segundo a los enemigos cercanos.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a4';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Implacable: +4% de velocidad de movimiento.\n Impulso: Moverte genera Impulso, lo que otorga hasta 40 de Velocidad de Movimiento al llegar a 100 acumulaciones. Atacar elimina todas las acumulaciones de Impulso. Las acumulaciones decaen cuando se afecta la velocidad de movimiento.\n Golpe Aplastante: Los ataques inflingen hasta 100 de daño mágico adicional segun el Impulso acumulado. Los ataques cuerpo a cuerpo que consumen el Impulso máximo también ralentizan un 75% durante 1 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a5';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Tormenta: +5% de Velocidad de Movimiento. \n Absorber: Al recibir daño mágico de campeones enemigos, obtienes una acumulación de Firmeza, con un máximo de 4 acumulaciones, durante 7 seg. Infligir daño a campeones enemigos restablece la duración. Con el máximo de acumulaciones, obtienes un 6% de Velocidad de Movimiento y 70 de Resistencia Mágica adicional.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a6';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Portador del Amanecer: Cuando inmovilizas a un campeón o te inmovilizan a 400 unidades de distancia de un campeón enemigo obtienes un 20% de Armadura y de Resistencia Mágica, revelas a los campeones enemigos cercanos durante 3 seg y les inflinges una cantidad de daño mágico equivalente a 40 mas un 2.5% de Vida adicional. (3 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0a7';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Corazón de Warmog: Si tienes al menos 1250 de vida adicional, recupera un 3.5% de vida máxima por seg si no has recibido daño en los ultimos 5 s. \n Bendito: Aumenta todos los efectos de curación y escudo sobre ti mismo en un 30%.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0ab';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Consumo colosal: Al estar a 700 unidades de un campeón enemigo, carga durante 2,5 s para asestarle un golpe tremendo. Este ataque cargado inflinge daño físico adicional equivalente a 140 + 3.5% de la vida máxima y otorga vida máxima equivalente al 15% del daño inflingido. Este efecto tiene 20 seg de enfriamiento por objetivo.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0ad';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asombro: Otorga Vida adicional igual al 15% de Maná Máximo y restaura el 15% de todo el maná gastado. \n Carga de Maná: Los ataques básicos, el gasto de Maná y el recibir daño de campeones, estructuras y monstruos épicos otorgan 14 de Maná Máximo. Este efecto otorga hasta 700 de Maná Máximo y se puede activar como máximo 3 veces cada 10 seg Limitado a un solo objeto de Lágrima de la Diosa.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0b0';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Asombro: Otorga Vida adicional igual al 15% de Maná Máximo y restaura el 15% de todo el maná gastado. \n Coloso Congelado: Cada vez que reduzcas el movimiento de un campeón enemigo, obtienes un escudo durante 3 seg que absorbe 120 + 4.5% de Maná Máximo. Si hay más de un campeón enemigo cerca, el escudo aumenta un 80% (8 seg de enfriamiento). Este escudo tiene un 50% de efectividad para campeones a distancia. \n Solo se activa al estar por encima del 20% de Maná Máximo. (8 seg de enfriamiento). El Escudo tiene un 50% de efectividad contra campeones a distancia.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0b1';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Verdugo de Gigantes: Inflinges daño adicional según la vida adicional del campeón enemigo. El límite de daño adicional es de un 12% y se alcanza cuando atacas a un campeón enemigo que tiene 1200 de Vida adicional.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0b2';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Pebetero: Cuando curas o escudas a un campeón aliado (es decir, un campeón que no seas tú), dicho campeón obtiene un 30% de Velocidad de Ataque y sus ataques inflingen 25 de daño mágico adicional durante 6 seg. Este daño puede asestar golpes críticos.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0b3';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Toque de fuego: Después de inflingir daño con un ataque o habilidad, quema al objetivo durante 3 seg, lo que inflinge un 1.4% de la Vida Máxima del objetivo como daño mágico por seg (el daño se reduce a un 0.7% para usuarios a distancia). Inflinge un 150% de daño contra súbditos y monstruos. Máximo de 125 de daño contra monstruos.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0b8';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Espinas: Al recibir un ataque de un campeon enemigo, inflinge 4 + 6% adicional (Armadura) de daño mágico al atacante. Entrelazado: Cuando recibes el ataque de un campeón enemigo o le inflinges daño, le aplicas un 40% de Heridas graves durante 3 s.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e0ba';
