update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Relicario: Otorga una escudo para ti y tus aliados cercanos que absorbe de 250 a 370 de daño durante 2.5 seg (60 seg de enfriamiento). \n\n
Si el objetivo recibió este efecto en los últimos 20 seg, el valor del escudo se reduce a la mitad$rd$::text)) where patch_id = 11 and item_id = '6a1cf21fc4bfa81cbdf50d09';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Jinete de la Tormenta: Al infligir daño equivalente al 25% de la Vida Máxima de un campeón en 2.5 seg, le aplicas Aguacero y obtienes un 25% de Velocidad de Movimiento durante 2.5 seg (25 seg de enfriamiento). \n\n
