update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Maldición: +5% de Velocidad de Movimiento.\n Espada Encantada: Usar una habilidad causa que el siguiente ataque dentro de 10 seg. inflinja daño mágico adicional igual al 75% de daño de ataque básico + 50% de poder de habilidad. (1.5 seg de enfriamiento). El daño se reduce contra estructuras.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e093';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Aflicción: Al inflingir daño mágico a los campeones enemigos aplica un 50% de Heridas Graves durante 3 seg.$rd$::text)) where patch_id = 11 and item_id = '6a04bc1334f787bb5bb2e07a';
