update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Vigilancia Nocturna: Obtienes 20 de Aceleración de Habilidad para la definitiva \\n Ráfaga Inicial: Después de lanzar tu definitiva, tus siguientes 3 ataques obtienen un 50% de Velocidad de Ataque y siempre asestan golpes críticos, que infligen un 85% de tu daño de Golpe Crítico normal durante 8 seg. Si un ataque ya asesta un golpe crítico, en su lugar inflige un 17.5% de daño verdadero adicional. (45 seg de enfriamiento).$rd$::text)) where patch_id = 11 and item_id = '68f6f056-2ea8-4c50-8d44-a0f14e520ea6';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Energizado: Se genera un ataque energizado al moverse y atacar \\n Francotirador: El ataque energizado inflige 80 de daño mágico adicional y otorga un 35% de alcance de ataque adicional, hasta un máximo de 150$rd$::text)) where patch_id = 11 and item_id = '7d70c694-3912-48ae-9b98-67a41b12f7fa';
