update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Magnificación: Los ataques infligen entre un 0% y un 10% de daño adicional según la distancia a la que se encuentre el enemigo y alcanzan el daño máximo a 550 unidades \n\n Precisión Arcana: Cuando un campeón al que le infligieron daño en los últimos 3 seg muere, obtienen 100 de alcance de ataque adicional durante 8 seg$rd$::text)) where patch_id = 11 and item_id = 'cd6aa587-8d9e-4195-b6f9-00174743e6b0';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Ataques energizados: Se genera un ataque energizado al moverse y atacar. \\n Electrochispa: Tu ataque energizado lanza una cadena de rayos que rebota hacia objetivos adicionales. Cantidad de Rebotes: 3/4/5/6, que aumenta en los niveles 1/5/9/13 e inflige 60 de daño mágico, el cual aumenta a 90 contra súbditos y monstruos. Aplica efectos al impacto a los objetivos secundarios del rebote. \\n Electrochoque: Los ataques básicos otorgan 7 acumulaciones adicionales de Energizado.$rd$::text)) where patch_id = 11 and item_id = 'e3c3992b-f516-4eea-8668-bb548db4cc13';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Armonía: Obtiene un 0.5% de Poder de curaciones y escudos adicional equivalente al Maná Máximo y recupera un 25% del Maná gastado \\n Carga de Maná: El gasto de Maná otorga 14 de Maná Máximo, hasta acumular 700. Esto puede activarse hasta 2 veces cada 10 seg. Al alcanzar el máximo de acumulaciones, se mejora automáticamente a Diadema Musical.$rd$::text)) where patch_id = 11 and item_id = '2e3e6027-0702-4245-9dbd-b81a5f5a9d07';
update public.item_patch_data set data = jsonb_set(data, '{description}', to_jsonb($rd$Armonía: Obtiene un 0.5% de Poder de curaciones y escudos adicional equivalente al Maná Máximo y recupera un 25% del Maná gastado \\n Diadema: Si tú o un campeón aliado al que hayas curado o protegido con un escudo en los últimos 3 seg están en combate, curas cada seg al campeón aliado cercano con la Vida más baja que se encuentre en un alcance de 800 unidades por una cantidad equivalente al 0.8% de tu Maná Máximo.$rd$::text)) where patch_id = 11 and item_id = 'c1140d29-16b8-4772-ad3a-7eb61006a85d';
